#!/bin/sh
# MainFrame installer for Linux - generated by vexelray-installer. Do not edit by hand; regenerate it.
#
#   curl -fsSL https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/mainframe/install.sh | sh
#
# Installs for your user only, without root: the files go to ~/.local/opt/<id> (or the folder the
# application chose), commands are linked into ~/.local/bin, the menu entry and file types go where
# freedesktop.org says (~/.local/share), and the install is recorded so uninstall.sh removes exactly it.
# Every download is checked against the SHA-256 in the application's manifest before anything is placed,
# and placing is journaled: a failed or interrupted install puts back what was there.
#
# Options, as environment variables for the sh that runs this (curl -fsSL <url> | INSTALL_NO_PATH=1 sh):
#   INSTALL_VERSION=1.2.3       install that version from the manifest's history
#   INSTALL_DIR=/path           install somewhere other than the default folder
#   INSTALL_NO_SHORTCUTS=1      no menu entry or desktop launcher
#   INSTALL_NO_PATH=1           link nothing into ~/.local/bin
#   INSTALL_NO_ASSOCIATIONS=1   register no file types
#   INSTALL_FORCE=1             reinstall the version that is installed
#   INSTALL_SKIP_CHECKS=1       install even when the system requirements are not met
# or as arguments: curl -fsSL <url> | sh -s -- --version 1.2.3 --dir /path --no-shortcuts --no-path
#   --no-associations --force --skip-checks
# An update keeps the last install's INSTALL_NO_* choices; INSTALL_NO_*=0 opts back in.
# INSTALL_REGISTRY_DIR moves the install records (for tests), as on Windows.

# shellcheck disable=SC2034
{
VI_ID='mainframe'
VI_NAME='MainFrame'
VI_PUBLISHER='sibarum'
VI_DESCRIPTION='A terminal window that wraps the native Windows shell over ConPTY, built on the VexelRay stack.'
VI_MANIFEST_URL='https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/mainframe/manifest.linux.txt'
VI_REGISTRY_DIR='$XDG_DATA_HOME/vexelray-installer/installs'
VI_ISSUES_URL='https://github.com/sibarum/vexelray-dist/issues/new'
}

set -u
vi_tab=$(printf '\t')
vi_nl='
'
VI_TX=
VI_TMP=
VI_LOCKDIR=
VI_OLD_VERSION=
VI_USED=

vi_say() { printf '%s\n' "$*"; }
vi_step() { printf '==> %s\n' "$*"; }
vi_info() { printf '    %s\n' "$*"; }
vi_warn() { printf 'Warning: %s\n' "$*" >&2; }
vi_on() { case ${1:-} in ''|0) return 1 ;; *) return 0 ;; esac; }

# A failure: put back what this run changed, say so, and stop.
vi_die() {
    printf 'ERROR: %s\n' "$*" >&2
    if [ -n "$VI_TX" ]; then
        vi_j=$VI_TX
        VI_TX=
        if vi_tx_rollback "$vi_j"; then
            if [ -n "$VI_OLD_VERSION" ]; then vi_say "$VI_NAME $VI_OLD_VERSION was put back as it was."
            else vi_say "Nothing was left installed."; fi
        else
            vi_say "Not everything could be put back; the next install of $VI_NAME will try again."
        fi
    fi
    [ -n "$VI_ISSUES_URL" ] && vi_say "To report the problem: $VI_ISSUES_URL"
    exit 1
}

vi_cleanup() {
    [ -n "$VI_TMP" ] && rm -rf -- "$VI_TMP"
    [ -n "$VI_LOCKDIR" ] && rm -rf -- "$VI_LOCKDIR"
}

# ~ and $VAR / ${VAR} from the environment; nothing in the text is run.
vi_expand() {
    printf '%s\n' "$1" | awk '{
        s = $0; out = ""
        if (s == "~" || substr(s, 1, 2) == "~/") { out = ENVIRON["HOME"]; s = substr(s, 2) }
        while (match(s, /\$\{[A-Za-z_][A-Za-z0-9_]*\}|\$[A-Za-z_][A-Za-z0-9_]*/)) {
            v = substr(s, RSTART, RLENGTH); gsub(/[${}]/, "", v)
            out = out substr(s, 1, RSTART - 1) ENVIRON[v]; s = substr(s, RSTART + RLENGTH)
        }
        print out s }'
}

vi_sha() {
    if command -v sha256sum >/dev/null 2>&1; then sha256sum < "$1" | cut -d' ' -f1
    else shasum -a 256 < "$1" | cut -d' ' -f1; fi
}

vi_size() { awk -v n="$1" 'BEGIN { if (n >= 1048576) printf "%.1f MB", n / 1048576; else printf "%d KB", (n + 1023) / 1024 }'; }

# vi_get URL FILE [resume]
vi_get() {
    if command -v curl >/dev/null 2>&1; then
        curl -fsSL --retry 3 --connect-timeout 30 ${3:+-C -} -o "$2" "$1"
    else
        wget -q --tries=3 ${3:+-c} -O "$2" "$1"
    fi
}

# Prints -1, 0 or 1. Numeric core part by part; a pre-release (1.2.0-rc1) sorts before its release.
vi_cmp() {
    awk -v a="$1" -v b="$2" '
        function key(v, k,   c, n, i, p) {
            sub(/^[vV]/, "", v); c = v; sub(/[-+].*$/, "", c); n = split(c, p, ".")
            for (i = 1; i <= 4; i++) k[i] = (i <= n ? p[i] + 0 : 0)
            return index(v, "-") > 0
        }
        BEGIN {
            pa = key(a, x); pb = key(b, y)
            for (i = 1; i <= 4; i++) { if (x[i] < y[i]) { print -1; exit } if (x[i] > y[i]) { print 1; exit } }
            print (pa && !pb) ? -1 : (!pa && pb) ? 1 : 0
        }'
}

# --- the manifest (manifest.linux.txt) and the install records (<id>.state) ---------------------------

# vi_rec KIND VERSION: the records of one version.
vi_rec() { awk -F'\t' -v k="$1" -v v="$2" '$1 == k && $2 == v' "$VI_MF"; }
vi_val() { awk -F'\t' -v k="$1" '$1 == k { print $2; exit }' "$VI_MF"; }
vi_val2() { awk -F'\t' -v k="$1" -v v="$2" '$1 == k && $2 == v { print $3; exit }' "$VI_MF"; }
# vi_state FILE KEY: a value of an install record.
vi_state() { awk -F'\t' -v k="$2" '$1 == k { print $2; exit }' "$1" 2>/dev/null; }
vi_state_opt() { awk -F'\t' -v k="$2" '$1 == "option" && $2 == k { print $3; exit }' "$1" 2>/dev/null; }
# vi_st FIELD...: one line of the new install record.
vi_st() { (IFS="$vi_tab"; printf '%s\n' "$*") >> "$VI_NEWSTATE"; }
vi_all_there() { while IFS= read -r vi_p; do [ -e "$vi_p" ] || [ -L "$vi_p" ] || return 1; done < "$1"; return 0; }
vi_join() { if [ "$2" = . ]; then printf '%s\n' "$1"; else printf '%s/%s\n' "$1" "$2"; fi; }
# A switch or INSTALL_NO_*=1 opts out, INSTALL_NO_*=0 back in; otherwise the last install's choice stands.
vi_optout() { case ${1:-} in '') printf '%s\n' "${2:-0}" ;; 0) echo 0 ;; *) echo 1 ;; esac; }

# The install record as JSON, the same shape the Windows installer writes, so other programs read either.
vi_record_json() {
    awk -F'\t' '
        function q(s) { gsub(/\\/, "\\\\", s); gsub(/"/, "\\\"", s); return "\"" s "\"" }
        function add(list, item) { return list (list == "" ? "" : ",\n") item }
        $1 ~ /^(id|name|publisher|version|platform|installedAt|updatedAt|installDir|manifestUrl)$/ { v[$1] = $2; next }
        $1 == "option" { opts = add(opts, "    " q($2) ": " ($3 == "1" ? "true" : "false")); next }
        $1 == "requires" { req = add(req, "    " q($2)); next }
        $1 == "command" { cmds = add(cmds, "    " q($2) ": { \"path\": " q($5) ", \"kind\": " q($3) ", \"version\": " q($4) " }"); next }
        $1 == "archive" { arcs = add(arcs, "    { \"name\": " q($2) ", \"version\": " q($4) ", \"sha256\": " q($3) ", \"dir\": " q($5) " }"); next }
        $1 == "file" { files = add(files, "    { \"path\": " q($6) ", \"kind\": " q($2) ", \"name\": " q($3) ", \"version\": " q($4) ", \"sha256\": " ($5 == "-" ? "null" : q($5)) " }"); next }
        $1 == "shortcut" { sc = add(sc, "    " q($2)); next }
        $1 == "link" { links = add(links, "    " q($2)); next }
        $1 == "assoc" { fa = add(fa, "    { \"extension\": " q($2) ", \"mimeType\": " q($3) ", \"isDefault\": " ($4 == "1" ? "true" : "false") ", \"desktopId\": " q($5) " }"); next }
        function arr(s) { return s == "" ? "[]" : "[\n" s "\n  ]" }
        function obj(s) { return s == "" ? "{}" : "{\n" s "\n  }" }
        END {
            printf "{\n  \"schemaVersion\": 1,\n"
            n = split("id name publisher version platform installedAt updatedAt installDir manifestUrl", k, " ")
            for (i = 1; i <= n; i++) printf "  %s: %s,\n", q(k[i]), q(v[k[i]])
            printf "  \"requires\": %s,\n  \"commands\": %s,\n  \"archives\": %s,\n  \"files\": %s,\n", arr(req), obj(cmds), arr(arcs), arr(files)
            printf "  \"shortcuts\": %s,\n  \"pathEntries\": %s,\n  \"fileAssociations\": %s,\n  \"options\": %s\n}\n", arr(sc), arr(links), arr(fa), obj(opts)
        }' "$1"
}

# --- one install at a time ----------------------------------------------------------------------------

vi_lock() {
    vi_l="$VI_REG/$VI_ID.lock"
    vi_tries=0
    while ! mkdir "$vi_l" 2>/dev/null; do
        vi_pid=$(cat "$vi_l/pid" 2>/dev/null)
        if [ -z "$vi_pid" ]; then sleep 1; vi_pid=$(cat "$vi_l/pid" 2>/dev/null); fi
        if [ -n "$vi_pid" ] && kill -0 "$vi_pid" 2>/dev/null; then
            vi_die "Another install of $VI_NAME is running (process $vi_pid). Wait for it to finish, then run this again."
        fi
        vi_tries=$((vi_tries + 1))
        [ "$vi_tries" -gt 3 ] && vi_die "Could not take the lock $vi_l."
        rm -rf -- "$vi_l"   # left by a run that was killed
    done
    VI_LOCKDIR=$vi_l
    echo $$ > "$vi_l/pid"
}

# --- the transaction ----------------------------------------------------------------------------------
# Every change goes into <registryDir>/<id>.journal before it is made: "put PATH BACKUP" (BACKUP is where
# the file that was there went, or - for none) and "dir PATH" (a folder this run created). A failure plays
# the journal backwards; a run that was killed is rolled back, or finished if it wrote "commit", by the next.

vi_tx_log() { (IFS="$vi_tab"; printf '%s\n' "$*") >> "$VI_TX" || vi_die "Cannot write $VI_TX."; }

vi_tx_begin() {
    VI_BK="$VI_ROOT/backup/$VI_ID"
    rm -rf -- "$VI_BK"
    mkdir -p "$VI_BK" || vi_die "Cannot create $VI_BK."
    VI_BKN=0
    VI_TX="$VI_REG/$VI_ID.journal"
    : > "$VI_TX" || vi_die "Cannot write $VI_TX."
    vi_tx_log backup "$VI_BK"
}

vi_mkdirs() {
    [ -d "$1" ] && return 0
    vi_mkdirs "$(dirname -- "$1")"
    vi_tx_log dir "$1"
    mkdir -- "$1" || vi_die "Cannot create $1."
}

# Moves a file (or link) out of the way, into the backup, so a rollback can put it back.
vi_aside() {
    if [ -e "$1" ] || [ -L "$1" ]; then
        VI_BKN=$((VI_BKN + 1))
        vi_tx_log put "$1" "$VI_BK/$VI_BKN"
        mv -f -- "$1" "$VI_BK/$VI_BKN" || vi_die "Cannot move $1 aside."
    fi
}

vi_prepare() {
    vi_mkdirs "$(dirname -- "$1")"
    if [ -e "$1" ] || [ -L "$1" ]; then vi_aside "$1"; else vi_tx_log put "$1" -; fi
}

# vi_put SOURCE TARGET MODE
vi_put() {
    vi_prepare "$2"
    cp -P -- "$1" "$2" || vi_die "Cannot write $2."
    [ -n "${3:-}" ] && { chmod "$3" "$2" || vi_die "Cannot set the mode of $2."; }
    return 0
}

vi_link() {
    vi_prepare "$2"
    ln -s -- "$1" "$2" || vi_die "Cannot link $2."
}

vi_tx_commit() {
    vi_tx_log commit
    rm -rf -- "$VI_BK"
    rm -f -- "$VI_TX"
    VI_TX=
}

vi_tx_rollback() {
    vi_rb=0
    vi_rbk=
    awk '{ l[NR] = $0 } END { for (i = NR; i > 0; i--) print l[i] }' "$1" > "$1.rev" || return 1
    while IFS="$vi_tab" read -r vi_op vi_a vi_b; do
        case $vi_op in
            put)
                if [ "$vi_b" = - ]; then rm -f -- "$vi_a" || vi_rb=1
                elif [ -e "$vi_b" ] || [ -L "$vi_b" ]; then rm -f -- "$vi_a"; mv -f -- "$vi_b" "$vi_a" || vi_rb=1; fi ;;
            dir) rmdir -- "$vi_a" 2>/dev/null ;;
            backup) vi_rbk=$vi_a ;;
        esac
    done < "$1.rev"
    rm -f -- "$1.rev"
    [ "$vi_rb" = 0 ] || return 1
    [ -n "$vi_rbk" ] && rm -rf -- "$vi_rbk"
    rm -f -- "$1"
    return 0
}

vi_tx_recover() {
    [ -f "$1" ] || return 0
    if grep -qx commit "$1"; then
        vi_rbk=$(awk -F'\t' '$1 == "backup" { print $2; exit }' "$1")
        [ -n "$vi_rbk" ] && rm -rf -- "$vi_rbk"
        rm -f -- "$1"
        return 0
    fi
    vi_say "The last install of $VI_NAME did not finish; putting back what it changed."
    vi_tx_rollback "$1" || vi_die "Could not put back what the unfinished install changed; see $1."
}

# --- downloads ----------------------------------------------------------------------------------------
# Into <registryDir>/../cache/<sha256>, through <sha256>.part, which a stopped download resumes from.

# vi_fetch URL SHA256 SIZE LABEL: sets VI_GOT to the verified file.
vi_fetch() {
    VI_GOT="$VI_CACHE/$2"
    if [ -f "$VI_GOT" ] && [ "$(vi_sha "$VI_GOT")" = "$2" ]; then
        vi_info "$4 (already downloaded)"
    else
        if [ "$3" = - ]; then vi_info "Downloading $4"; else vi_info "Downloading $4 ($(vi_size "$3"))"; fi
        vi_part="$VI_CACHE/$2.part"
        if ! vi_get "$1" "$vi_part" resume; then
            rm -f -- "$vi_part"
            vi_get "$1" "$vi_part" || vi_die "Could not download $1."
        fi
        if [ "$(vi_sha "$vi_part")" != "$2" ]; then
            rm -f -- "$vi_part"
            vi_die "$4 does not match the SHA-256 in the manifest, so it was not installed. Try again later; if it keeps happening, report it."
        fi
        mv -f -- "$vi_part" "$VI_GOT" || vi_die "Cannot write $VI_GOT."
    fi
    VI_USED="$VI_USED$VI_GOT$vi_nl"
}

# vi_untar TARBALL FOLDER LABEL
vi_untar() {
    tar -tzf "$1" > "$VI_TMP/entries" 2>/dev/null || vi_die "$3 is not a valid .tar.gz."
    if awk '{ n = $0; sub(/^(\.\/)+/, "", n) } n ~ /^\// || n ~ /(^|\/)\.\.(\/|$)/ { bad = 1 } END { exit !bad }' "$VI_TMP/entries"; then
        vi_die "$3 has an entry outside the folder it unpacks into; it was not installed."
    fi
    mkdir -p -- "$2" && tar -xzf "$1" -C "$2" || vi_die "Could not unpack $3."
}

# --- system requirements ------------------------------------------------------------------------------

vi_req_failed() { VI_FAILED="$VI_FAILED$1 (found: $2)$vi_nl"; }
vi_req_unknown() { VI_UNKNOWN="$VI_UNKNOWN$1 ($2)$vi_nl"; }

# vi_check_vulkan VERSION " EXT EXT...": one Vulkan device must have the version and every extension.
vi_check_vulkan() {
    vi_what="a GPU with Vulkan $1"
    [ -n "$2" ] && vi_what="$vi_what and$2"
    if ! command -v vulkaninfo >/dev/null 2>&1; then
        vi_req_unknown "$vi_what" "vulkaninfo is not installed; it is in the vulkan-tools package"
        return 0
    fi
    if command -v timeout >/dev/null 2>&1; then vi_vk=$(timeout 60 vulkaninfo 2>/dev/null); else vi_vk=$(vulkaninfo 2>/dev/null); fi
    vi_res=$(printf '%s\n' "$vi_vk" | awk -v want="$1" -v exts="$2" '
        function ver(s,   p) { split(s, p, "."); return p[1] * 1000000 + p[2] * 1000 + p[3] }
        function gpu_done(   ok, n, e, i, miss) {
            if (gpu == "") return
            ok = (api != "" && ver(api) >= ver(want)); miss = ""
            n = split(exts, e, " ")
            for (i = 1; i <= n; i++) if (!(e[i] in has)) { ok = 0; miss = miss " " e[i] }
            if (ok) found = 1
            desc = desc (desc == "" ? "" : "; ") (name == "" ? gpu : name) ": Vulkan " (api == "" ? "?" : api) (miss == "" ? "" : ", without" miss)
            split("", has); api = ""; name = ""
        }
        /^GPU[0-9]+:/ { gpu_done(); gpu = $1; seen = 1; next }
        gpu != "" && api == "" && /apiVersion/ { if (match($0, /[0-9]+\.[0-9]+\.[0-9]+/)) api = substr($0, RSTART, RLENGTH) }
        gpu != "" && name == "" && /deviceName/ { s = $0; sub(/^[^=]*=[ \t]*/, "", s); name = s }
        gpu != "" && /^[ \t]+VK_[A-Za-z0-9_]+[ \t]*:/ { x = $1; sub(/:.*/, "", x); has[x] = 1 }
        END { gpu_done(); if (!seen) print "unknown"; else if (found) print "ok"; else print "fail\t" desc }')
    case $vi_res in
        ok) ;;
        unknown) vi_req_unknown "$vi_what" "vulkaninfo found no Vulkan device, or printed what this does not read" ;;
        *) vi_req_failed "$vi_what" "${vi_res#fail$vi_tab}" ;;
    esac
}

# vi_check_system VERSION INSTALL-DIR: sets VI_FAILED and VI_UNKNOWN, one requirement a line.
vi_check_system() {
    VI_FAILED=
    VI_UNKNOWN=
    VI_CHECKED=
    vi_arch=$(vi_val2 arch "$1")
    if [ -n "$vi_arch" ]; then
        VI_CHECKED=1
        vi_m=$(uname -m)
        [ "$vi_m" = "$vi_arch" ] || vi_req_failed "a $vi_arch processor" "$vi_m"
    fi
    vi_rec system "$1" > "$VI_TMP/system"
    vi_vkv=
    vi_exts=
    while IFS="$vi_tab" read -r vi_k _ vi_key vi_val; do
        VI_CHECKED=1
        case $vi_key in
            memoryMb)
                vi_have=$(awk '/^MemTotal:/ { print int($2 / 1024); exit }' /proc/meminfo 2>/dev/null)
                if [ -z "$vi_have" ]; then vi_req_unknown "$vi_val MB of memory" "/proc/meminfo is not readable"
                elif [ "$vi_have" -lt "$vi_val" ]; then vi_req_failed "$vi_val MB of memory" "$vi_have MB"; fi ;;
            diskMb)
                vi_d=$2
                while [ ! -d "$vi_d" ]; do vi_d=$(dirname -- "$vi_d"); done
                vi_have=$(df -Pk -- "$vi_d" 2>/dev/null | awk 'NR == 2 { print int($4 / 1024) }')
                if [ -z "$vi_have" ]; then vi_req_unknown "$vi_val MB free for $2" "df did not say"
                elif [ "$vi_have" -lt "$vi_val" ]; then vi_req_failed "$vi_val MB free for $2" "$vi_have MB"; fi ;;
            glibc)
                if ! command -v getconf >/dev/null 2>&1; then vi_req_unknown "glibc $vi_val or newer" "getconf is not installed"
                else
                    vi_g=$(getconf GNU_LIBC_VERSION 2>/dev/null)
                    vi_g=${vi_g#glibc }
                    if [ -z "$vi_g" ]; then vi_req_failed "glibc $vi_val or newer" "another C library, such as musl"
                    elif [ "$(vi_cmp "$vi_g" "$vi_val")" -lt 0 ]; then vi_req_failed "glibc $vi_val or newer" "glibc $vi_g"; fi
                fi ;;
            vulkan) vi_vkv=$vi_val ;;
            vulkanExtension) vi_exts="$vi_exts $vi_val" ;;
        esac
    done < "$VI_TMP/system"
    if [ -n "$vi_vkv$vi_exts" ]; then vi_check_vulkan "${vi_vkv:-1.0}" "$vi_exts"; fi
}

# --- java ---------------------------------------------------------------------------------------------

vi_find_java() {
    if [ -n "${JAVA_HOME:-}" ] && [ -x "$JAVA_HOME/bin/java" ]; then printf '%s\n' "$JAVA_HOME/bin/java"; return 0; fi
    command -v java 2>/dev/null
}

vi_java_major() {
    "$1" -version 2>&1 | awk -F'"' '/version/ { v = $2; if (v ~ /^1\./) { split(v, p, "."); print p[2] } else { split(v, p, /[.+-]/); print p[1] } exit }'
}

# A word sh reads as exactly $1.
vi_sq() { printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"; }

# vi_launcher JAR RUNTIME-ID JVMARGS-FILE NAME: the script that starts a jar, as a <name>.cmd does on Windows.
vi_launcher() {
    printf '#!/bin/sh\n'
    printf '# %s launcher, written by the %s installer (vexelray-installer).\n' "$4" "$VI_NAME"
    printf 'java=\n'
    if [ "$2" != - ]; then
        printf 'home=$(cat %s 2>/dev/null)\n' "$(vi_sq "$VI_REG/$2.home")"
        printf 'if [ -n "$home" ] && [ -x "$home/bin/java" ]; then java="$home/bin/java"; else\n'
        printf '    echo %s >&2; exit 1\nfi\n' "$(vi_sq "$4 needs '$2' to be installed: it provides the Java runtime.")"
    else
        printf 'if [ -n "${JAVA_HOME:-}" ] && [ -x "$JAVA_HOME/bin/java" ]; then java="$JAVA_HOME/bin/java"; fi\n'
        printf '[ -n "$java" ] || java=$(command -v java) || { echo %s >&2; exit 1; }\n' "$(vi_sq "$4 needs Java: install it, or set JAVA_HOME.")"
    fi
    printf 'exec "$java"'
    while IFS= read -r vi_ja; do printf ' %s' "$(vi_sq "$vi_ja")"; done < "$3"
    printf ' -jar %s "$@"\n' "$(vi_sq "$1")"
}

# --- menus, desktop, file types -----------------------------------------------------------------------

vi_desktop_id() { printf 'vexelray-%s-%s.desktop\n' "$VI_ID" "$(printf '%s' "$1" | tr -c 'A-Za-z0-9._-' '-')"; }

# A path an Exec line can quote as it is; the escapes the desktop entry spec has for the rest are not worth it.
vi_exec_ok() { case $1 in *[\"\`\$\\%]*) return 1 ;; *) return 0 ;; esac; }

# vi_desktop_entry FILE LABEL EXEC ICON TERMINAL MIME-TYPES HIDDEN
vi_desktop_entry() {
    {
        printf '[Desktop Entry]\nType=Application\nVersion=1.0\n'
        printf 'Name=%s\n' "$2"
        printf 'Comment=%s\n' "$(printf '%s' "$VI_DESCRIPTION" | tr '\n\t' '  ')"
        if [ -n "$6" ]; then printf 'Exec="%s" %%f\n' "$3"; else printf 'Exec="%s"\n' "$3"; fi
        [ -n "$4" ] && printf 'Icon=%s\n' "$4"
        printf 'Terminal=%s\n' "$5"
        [ -n "$6" ] && printf 'MimeType=%s\n' "$6"
        [ "$7" = 1 ] && printf 'NoDisplay=true\n'
        printf 'X-Vexelray-Installer=%s\n' "$VI_ID"
    } > "$1"
}

# Takes our desktop entry out of the default for a type, in mimeapps.list; other programs' entries stay.
vi_mimeapps_drop() {
    vi_f="$VI_CONFIG_HOME/mimeapps.list"
    [ -f "$vi_f" ] || return 0
    awk -v m="$1" -v d="$2" '
        /^\[/ { sec = $0 }
        sec == "[Default Applications]" && index($0, m "=") == 1 {
            n = split(substr($0, length(m) + 2), v, ";"); out = ""
            for (i = 1; i <= n; i++) if (v[i] != "" && v[i] != d) out = out v[i] ";"
            if (out != "") print m "=" out
            next
        }
        { print }' "$vi_f" > "$vi_f.vi-new" && mv -f -- "$vi_f.vi-new" "$vi_f"
}

vi_xml() { printf '%s' "$1" | sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' -e 's/"/\&quot;/g'; }

vi_refresh_desktop() {
    command -v update-desktop-database >/dev/null 2>&1 && update-desktop-database -q "$XDG_DATA_HOME/applications" 2>/dev/null
    command -v update-mime-database >/dev/null 2>&1 && [ -d "$XDG_DATA_HOME/mime/packages" ] && update-mime-database "$XDG_DATA_HOME/mime" >/dev/null 2>&1
    [ -d "$XDG_DATA_HOME/icons/hicolor" ] && touch "$XDG_DATA_HOME/icons/hicolor" 2>/dev/null
    return 0
}

# --- install ------------------------------------------------------------------------------------------

vi_main() {
    while [ $# -gt 0 ]; do
        case $1 in
            --version) shift; INSTALL_VERSION=${1:-} ;;
            --dir) shift; INSTALL_DIR=${1:-} ;;
            --no-shortcuts) INSTALL_NO_SHORTCUTS=1 ;;
            --no-path) INSTALL_NO_PATH=1 ;;
            --no-associations) INSTALL_NO_ASSOCIATIONS=1 ;;
            --force) INSTALL_FORCE=1 ;;
            --skip-checks) INSTALL_SKIP_CHECKS=1 ;;
            --quiet|--do-not-prompt-me) ;;
            *) vi_warn "Ignoring unknown argument: $1" ;;
        esac
        [ $# -gt 0 ] && shift
    done

    # INSTALL_ANY_OS is for the installer's own tests, which run it elsewhere
    if [ "$(uname -s 2>/dev/null)" != Linux ] && ! vi_on "${INSTALL_ANY_OS:-}"; then
        vi_die "This is the Linux installer of $VI_NAME. On Windows, run the PowerShell command from the same page."
    fi
    [ -n "${HOME:-}" ] || vi_die "HOME is not set."
    command -v curl >/dev/null 2>&1 || command -v wget >/dev/null 2>&1 || vi_die "Neither curl nor wget is installed; install one of them."
    command -v sha256sum >/dev/null 2>&1 || command -v shasum >/dev/null 2>&1 || vi_die "sha256sum is not installed (it is in coreutils)."
    command -v tar >/dev/null 2>&1 || vi_die "tar is not installed."
    export XDG_DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
    VI_CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"

    VI_REG=${INSTALL_REGISTRY_DIR:-}
    [ -n "$VI_REG" ] || VI_REG=$(vi_expand "$VI_REGISTRY_DIR")
    VI_ROOT=$(dirname -- "$VI_REG")
    VI_CACHE="$VI_ROOT/cache"
    mkdir -p -- "$VI_REG" "$VI_CACHE" || vi_die "Cannot create $VI_REG."
    VI_TMP=$(mktemp -d "${TMPDIR:-/tmp}/vi-install.XXXXXX") || vi_die "Cannot create a temporary folder."
    trap vi_cleanup EXIT
    trap 'vi_die "Interrupted."' INT TERM HUP

    vi_step "Fetching install manifest"
    VI_MF="$VI_TMP/manifest.txt"
    vi_get "$VI_MANIFEST_URL" "$VI_MF" || vi_die "Could not download $VI_MANIFEST_URL."
    [ "$(head -n 1 "$VI_MF")" = "vexelray-installer-linux${vi_tab}1" ] || vi_die "$VI_MANIFEST_URL is not a manifest this installer reads."
    [ "$(vi_val id)" = "$VI_ID" ] || vi_die "The manifest is for '$(vi_val id)', not '$VI_ID'."
    want=${INSTALL_VERSION:-}
    want=${want#[vV]}
    [ -n "$want" ] || want=$(vi_val latest)
    if [ -z "$want" ] || [ -z "$(vi_rec version "$want")" ]; then
        vi_die "$VI_NAME '$want' has no Linux build. Available: $(awk -F'\t' '$1 == "version" { printf "%s%s", s, $2; s = ", " }' "$VI_MF")"
    fi

    vi_rec needs "$want" > "$VI_TMP/needs"
    while IFS="$vi_tab" read -r vi_k _ rid rmin; do
        rver=$(vi_state "$VI_REG/$rid.state" version)
        [ -n "$rver" ] || vi_die "$VI_NAME needs '$rid' to be installed first. Install it, then run this again."
        if [ "$rmin" != - ] && [ "$(vi_cmp "$rver" "$rmin")" -lt 0 ]; then
            vi_die "$VI_NAME needs $rid $rmin or newer, but $rver is installed. Update it first."
        fi
    done < "$VI_TMP/needs"

    vi_lock
    vi_tx_recover "$VI_REG/$VI_ID.journal"
    find "$VI_CACHE" -type f -mtime +14 -exec rm -f {} + 2>/dev/null

    old="$VI_REG/$VI_ID.state"
    [ -f "$old" ] || old=/dev/null
    VI_OLD_VERSION=$(vi_state "$old" version)
    old_dir=$(vi_state "$old" installDir)
    if [ -n "${INSTALL_DIR:-}" ]; then dir=$(vi_expand "$INSTALL_DIR")
    elif [ -n "$old_dir" ]; then dir=$old_dir
    else dir=$(vi_expand "$(vi_val2 dir "$want")"); fi
    case $dir in /*) ;; *) dir="$PWD/$dir" ;; esac
    while [ "${dir%/}" != "$dir" ]; do dir=${dir%/}; done
    case $dir in ''|"$HOME"|*"$vi_tab"*) vi_die "'$dir' cannot be the install folder; give it a folder of its own." ;; esac

    no_sc=$(vi_optout "${INSTALL_NO_SHORTCUTS:-}" "$(vi_state_opt "$old" noShortcuts)")
    no_path=$(vi_optout "${INSTALL_NO_PATH:-}" "$(vi_state_opt "$old" noPath)")
    no_assoc=$(vi_optout "${INSTALL_NO_ASSOCIATIONS:-}" "$(vi_state_opt "$old" noAssociations)")

    if [ "$VI_OLD_VERSION" = "$want" ] && [ "$old_dir" = "$dir" ] && ! vi_on "${INSTALL_FORCE:-}"; then
        vi_say "$VI_NAME $want is already installed in $dir. Set INSTALL_FORCE=1 to reinstall."
        return 0
    fi

    vi_check_system "$want" "$dir"
    if [ -n "$VI_CHECKED" ]; then
        vi_step "Checking system requirements"
        printf '%s' "$VI_UNKNOWN" | while IFS= read -r vi_l; do vi_warn "Could not check: $vi_l"; done
        if [ -n "$VI_FAILED" ]; then
            printf '%s' "$VI_FAILED" | while IFS= read -r vi_l; do printf '    Not met: %s\n' "$vi_l"; done
            if vi_on "${INSTALL_SKIP_CHECKS:-}"; then vi_warn "Installing anyway, as INSTALL_SKIP_CHECKS is set. $VI_NAME may not start or may misbehave."
            else vi_die "This computer does not meet the system requirements of $VI_NAME. Nothing was installed. Set INSTALL_SKIP_CHECKS=1 to install anyway."; fi
        else
            vi_info "Met"
        fi
    fi

    jmin=$(vi_val2 java "$want")
    if [ -n "$jmin" ]; then
        java=$(vi_find_java)
        if [ -z "$java" ]; then
            vi_warn "Java was not found. $VI_NAME needs a Java runtime$([ "$jmin" != 0 ] && printf ' (version %s or newer)' "$jmin") on PATH or in JAVA_HOME to start."
        elif [ "$jmin" != 0 ]; then
            jmaj=$(vi_java_major "$java")
            [ -n "$jmaj" ] && [ "$jmaj" -lt "$jmin" ] && vi_warn "Java $jmaj found at $java, but $VI_NAME needs Java $jmin or newer."
        fi
    fi

    # 1. download and check everything before the install folder is touched
    vi_step "Downloading $VI_NAME $want"
    got="$VI_TMP/got"
    : > "$got"
    for t in uninstall.sh update.sh; do
        vi_t=$(awk -F'\t' -v t="$t" '$1 == "tool" && $2 == t' "$VI_MF")
        [ -n "$vi_t" ] || continue
        IFS="$vi_tab" read -r vi_k vi_n tsha turl <<EOF
$vi_t
EOF
        if [ -f "$dir/$t" ] && [ "$(vi_sha "$dir/$t")" = "$tsha" ]; then printf 'tool\t%s\t%s\t-\n' "$t" "$tsha" >> "$got"; continue; fi
        vi_fetch "$turl" "$tsha" - "$t"
        printf 'tool\t%s\t%s\t%s\n' "$t" "$tsha" "$VI_GOT" >> "$got"
    done
    vi_rec bin "$want" > "$VI_TMP/bins"
    vi_i=0
    while IFS="$vi_tab" read -r vi_k _ name kind bver sha size onpath file url rel; do
        vi_i=$((vi_i + 1))
        target=$(vi_join "$dir" "$rel")
        if [ "$kind" = archive ]; then
            # current when the last install unpacked the same archive into the same folder, and all of it is still there
            if awk -F'\t' -v n="$name" -v s="$sha" -v d="$target" '
                    $1 == "archive" && $2 == n && $3 == s && $5 == d { same = 1 }
                    $1 == "file" && $2 == "archive-file" && $3 == n { print $6 }
                    END { exit !same }' "$old" > "$VI_TMP/arc-$vi_i" && vi_all_there "$VI_TMP/arc-$vi_i"; then
                vi_info "$file is already current"
                printf 'keep\t%s\t-\n' "$name" >> "$got"
                continue
            fi
            vi_fetch "$url" "$sha" "$size" "$file"
            vi_info "Unpacking $file"
            vi_untar "$VI_GOT" "$VI_TMP/x-$vi_i" "$file"
            printf 'bin\t%s\t%s\n' "$name" "$VI_TMP/x-$vi_i" >> "$got"
        elif [ -f "$target" ] && [ "$(vi_sha "$target")" = "$sha" ]; then
            vi_info "$file is already current"
        else
            vi_fetch "$url" "$sha" "$size" "$file"
            printf 'bin\t%s\t%s\n' "$name" "$VI_GOT" >> "$got"
        fi
    done < "$VI_TMP/bins"
    { vi_rec icon "$want"; vi_rec typeicon "$want"; } > "$VI_TMP/icons"
    while IFS="$vi_tab" read -r vi_k _ name isha ipx ifile iurl irel; do
        itarget=$(vi_join "$dir" "$irel")
        if [ -f "$itarget" ] && [ "$(vi_sha "$itarget")" = "$isha" ]; then continue; fi
        vi_fetch "$iurl" "$isha" - "$ifile"
        printf 'icon\t%s\t%s\n' "$irel" "$VI_GOT" >> "$got"
    done < "$VI_TMP/icons"

    # 2. place the files; from here on everything goes through the journal until the commit
    vi_step "Installing to $dir"
    VI_NEWSTATE="$VI_TMP/state"
    : > "$VI_NEWSTATE"
    now=$(date -u +%Y-%m-%dT%H:%M:%SZ)
    installed_at=$(vi_state "$old" installedAt)
    vi_st id "$VI_ID"
    vi_st name "$VI_NAME"
    vi_st publisher "$VI_PUBLISHER"
    vi_st version "$want"
    vi_st platform linux
    vi_st installedAt "${installed_at:-$now}"
    vi_st updatedAt "$now"
    vi_st installDir "$dir"
    vi_st manifestUrl "$VI_MANIFEST_URL"
    vi_st option noShortcuts "$no_sc"
    vi_st option noPath "$no_path"
    vi_st option noAssociations "$no_assoc"
    vi_rec needs "$want" | while IFS="$vi_tab" read -r vi_k _ rid rmin; do vi_st requires "$rid"; done

    vi_tx_begin
    vi_mkdirs "$dir"
    vi_i=0
    while IFS="$vi_tab" read -r vi_k _ name kind bver sha size onpath file url rel; do
        vi_i=$((vi_i + 1))
        target=$(vi_join "$dir" "$rel")
        src=$(awk -F'\t' -v n="$name" '$1 == "bin" && $2 == n { print $3; exit }' "$got")
        if [ "$kind" = archive ]; then
            vi_mkdirs "$target"
            if [ -n "$src" ]; then
                (cd "$src" && find . \( -type f -o -type l \) -print) | sed 's|^\./||' | sort > "$VI_TMP/files-$vi_i"
                while IFS= read -r vi_p; do
                    vi_put "$src/$vi_p" "$target/$vi_p"
                    vi_st file archive-file "$name" "$bver" - "$target/$vi_p"
                done < "$VI_TMP/files-$vi_i"
            else
                while IFS= read -r vi_p; do vi_st file archive-file "$name" "$bver" - "$vi_p"; done < "$VI_TMP/arc-$vi_i"
            fi
            vi_st archive "$name" "$sha" "$bver" "$target"
            vi_rec expose "$want" | awk -F'\t' -v n="$name" '$3 == n' > "$VI_TMP/exp"
            while IFS="$vi_tab" read -r vi_k _ vi_n cmd erel; do vi_st command "$cmd" native "$bver" "$target/$erel"; done < "$VI_TMP/exp"
            continue
        fi
        case $kind in native) mode=755 ;; *) mode=644 ;; esac
        if [ -n "$src" ]; then vi_put "$src" "$target" "$mode"; else chmod "$mode" "$target" 2>/dev/null; fi
        vi_st file binary "$name" "$bver" "$sha" "$target"
        run=$target
        if [ "$kind" = jar ]; then
            lrel=$(vi_rec launcher "$want" | awk -F'\t' -v n="$name" '$3 == n { print $4; exit }')
            runtime=$(vi_rec runtime "$want" | awk -F'\t' -v n="$name" '$3 == n { print $4; exit }')
            vi_rec jvmarg "$want" | awk -F'\t' -v n="$name" '$3 == n { print $4 }' > "$VI_TMP/jvm"
            run=$(vi_join "$dir" "$lrel")
            vi_launcher "$target" "${runtime:--}" "$VI_TMP/jvm" "$name" > "$VI_TMP/launcher"
            vi_put "$VI_TMP/launcher" "$run" 755
            vi_st file launcher "$name" "$bver" "$(vi_sha "$run")" "$run"
        fi
        [ "$kind" = file ] || vi_st command "$name" "$kind" "$bver" "$run"
    done < "$VI_TMP/bins"
    while IFS="$vi_tab" read -r vi_k _ name isha ipx ifile iurl irel; do
        itarget=$(vi_join "$dir" "$irel")
        src=$(awk -F'\t' -v r="$irel" '$1 == "icon" && $2 == r { print $3; exit }' "$got")
        [ -n "$src" ] && vi_put "$src" "$itarget" 644
        if [ "$vi_k" = icon ]; then vi_st file icon "$name" "$want" "$isha" "$itarget"; else vi_st file file-icon "$name" "$want" "$isha" "$itarget"; fi
    done < "$VI_TMP/icons"
    while IFS="$vi_tab" read -r vi_k t tsha src; do
        [ "$vi_k" = tool ] || continue
        [ "$src" != - ] && vi_put "$src" "$dir/$t" 755
        vi_st file tool "$t" "$want" "$tsha" "$dir/$t"
    done < "$got"
    # other installs' launchers find this one through it (a jar's runtime)
    printf '%s\n' "$dir" > "$VI_TMP/home"
    vi_put "$VI_TMP/home" "$VI_REG/$VI_ID.home" 644
    vi_st file pointer "$VI_ID.home" "$want" "$(vi_sha "$VI_REG/$VI_ID.home")" "$VI_REG/$VI_ID.home"

    # 3. menu entries and desktop launchers, written in the temporary folder and put in place like any file
    apps="$XDG_DATA_HOME/applications"
    desktop_dir=
    if command -v xdg-user-dir >/dev/null 2>&1; then desktop_dir=$(xdg-user-dir DESKTOP 2>/dev/null); fi
    [ -n "$desktop_dir" ] || desktop_dir="$HOME/Desktop"
    [ "$desktop_dir" = "$HOME" ] && desktop_dir=
    vi_rec assoc "$want" > "$VI_TMP/assocs"
    : > "$VI_TMP/defaults"
    while IFS="$vi_tab" read -r vi_k _ name kind bver sha size onpath file url rel; do
        [ "$kind" = native ] || [ "$kind" = jar ] || continue
        sc=$(vi_rec shortcut "$want" | awk -F'\t' -v n="$name" '$3 == n')
        mimes=
        if [ "$no_assoc" = 0 ]; then mimes=$(awk -F'\t' -v n="$name" '$3 == n { printf "%s;", $5 }' "$VI_TMP/assocs"); fi
        [ -n "$sc" ] || [ -n "$mimes" ] || continue
        run=$(awk -F'\t' -v n="$name" '$1 == "command" && $2 == n { print $5; exit }' "$VI_NEWSTATE")
        if ! vi_exec_ok "$run"; then vi_warn "No menu entry or file types for $name: its path has a character a desktop entry cannot hold ($run)."; continue; fi
        icon=$(awk -F'\t' -v n="$name" '$1 == "file" && $2 == "icon" && $3 == n { print $6; exit }' "$VI_NEWSTATE")
        id=$(vi_desktop_id "$name")
        if [ -n "$sc" ]; then
            IFS="$vi_tab" read -r vi_k _ vi_n sdesk smenu sgui label <<EOF
$sc
EOF
        else sdesk=0; smenu=0; sgui=1; label=$name; fi
        [ "$no_sc" = 1 ] && { sdesk=0; smenu=0; }
        [ "$sgui" = 1 ] && term=false || term=true
        if [ "$smenu" = 1 ] || [ -n "$mimes" ]; then
            hidden=1
            [ "$smenu" = 1 ] && hidden=0
            vi_desktop_entry "$VI_TMP/$id" "$label" "$run" "$icon" "$term" "$mimes" "$hidden"
            vi_put "$VI_TMP/$id" "$apps/$id" 644
            vi_st shortcut "$apps/$id"
            [ "$hidden" = 0 ] && vi_info "Menu entry: $label"
        fi
        if [ "$sdesk" = 1 ] && [ -n "$desktop_dir" ] && [ -d "$desktop_dir" ]; then
            vi_desktop_entry "$VI_TMP/d-$id" "$label" "$run" "$icon" "$term" "" 0
            vi_put "$VI_TMP/d-$id" "$desktop_dir/$id" 755
            command -v gio >/dev/null 2>&1 && gio set "$desktop_dir/$id" metadata::trusted true >/dev/null 2>&1
            vi_st shortcut "$desktop_dir/$id"
            vi_info "Desktop launcher: $desktop_dir/$id"
        fi
        # a file type becomes ours by default only when no program is its default yet
        if [ -n "$mimes" ]; then
            awk -F'\t' -v n="$name" '$3 == n' "$VI_TMP/assocs" > "$VI_TMP/mine"
            while IFS="$vi_tab" read -r vi_k _ vi_n ext mime own ficon desc; do
                isdef=0
                if command -v xdg-mime >/dev/null 2>&1; then
                    cur=$(xdg-mime query default "$mime" 2>/dev/null)
                    if [ -z "$cur" ] || [ "$cur" = "$id" ]; then isdef=1; printf '%s\t%s\n' "$mime" "$id" >> "$VI_TMP/defaults"; fi
                fi
                vi_st assoc "$ext" "$mime" "$isdef" "$id"
                if [ "$isdef" = 1 ]; then vi_info "Opens $ext files (default)"; else vi_info "Opens $ext files (listed under Open With)"; fi
            done < "$VI_TMP/mine"
        fi
    done < "$VI_TMP/bins"

    # 4. file types: a shared-mime-info package for the extensions, and an icon for the types made up here
    if [ "$no_assoc" = 0 ] && [ -s "$VI_TMP/assocs" ]; then
        xml="$XDG_DATA_HOME/mime/packages/vexelray-$VI_ID.xml"
        {
            printf '<?xml version="1.0" encoding="UTF-8"?>\n'
            printf '<mime-info xmlns="http://www.freedesktop.org/standards/shared-mime-info">\n'
            while IFS="$vi_tab" read -r vi_k _ vi_n ext mime own ficon desc; do
                printf '  <mime-type type="%s">\n' "$(vi_xml "$mime")"
                [ "$own" = 1 ] && printf '    <comment>%s</comment>\n' "$(vi_xml "$desc")"
                # below the usual weight, so an extension another type already has keeps it
                printf '    <glob pattern="*%s" weight="40"/>\n' "$(vi_xml "$ext")"
                printf '  </mime-type>\n'
            done < "$VI_TMP/assocs"
            printf '</mime-info>\n'
        } > "$VI_TMP/mime.xml"
        vi_put "$VI_TMP/mime.xml" "$xml" 644
        vi_st file mime "$VI_ID" "$want" "$(vi_sha "$xml")" "$xml"
        while IFS="$vi_tab" read -r vi_k _ vi_n ext mime own ficon desc; do
            [ "$own" = 1 ] || continue
            if [ "$ficon" != - ]; then
                ipath=$(awk -F'\t' -v n="$vi_n" -v f="$ficon" '$1 == "typeicon" && $3 == n && $6 == f { print $5 "\t" $8; exit }' "$VI_TMP/icons")
            else
                ipath=$(awk -F'\t' -v n="$vi_n" '$1 == "icon" && $3 == n { print $5 "\t" $8; exit }' "$VI_TMP/icons")
            fi
            [ -n "$ipath" ] || continue
            ipx=${ipath%%"$vi_tab"*}
            isrc=$(vi_join "$dir" "${ipath#*"$vi_tab"}")
            idst="$XDG_DATA_HOME/icons/hicolor/${ipx}x${ipx}/mimetypes/$(printf '%s' "$mime" | tr '/' '-').png"
            vi_put "$isrc" "$idst" 644
            vi_st file type-icon "$vi_n" "$want" "$(vi_sha "$idst")" "$idst"
        done < "$VI_TMP/assocs"
    fi

    # 5. commands on PATH: links in ~/.local/bin, never over a file that is not one of ours
    bindir="$HOME/.local/bin"
    if [ "$no_path" = 0 ]; then
        while IFS="$vi_tab" read -r vi_k _ name kind bver sha size onpath file url rel; do
            [ "$onpath" = 1 ] || continue
            run=$(awk -F'\t' -v n="$name" '$1 == "command" && $2 == n { print $5; exit }' "$VI_NEWSTATE")
            [ -n "$run" ] || continue
            lnk="$bindir/$(printf '%s' "$name" | tr -c 'A-Za-z0-9._-' '-')"
            if [ -e "$lnk" ] || [ -L "$lnk" ]; then
                # ours when the last install recorded it, or when it already points here
                if ! awk -F'\t' -v l="$lnk" '$1 == "link" && $2 == l { f = 1 } END { exit !f }' "$old" \
                        && ! { [ -L "$lnk" ] && [ "$(readlink "$lnk")" = "$run" ]; }; then
                    vi_warn "$lnk is already there and is not $VI_NAME's, so it was left alone; $run is not on PATH."
                    continue
                fi
            fi
            vi_link "$run" "$lnk"
            vi_st link "$lnk"
            vi_info "On PATH: $lnk"
        done < "$VI_TMP/bins"
    fi

    # 6. what the last install had and this one does not goes into the backup too, so a rollback restores it
    awk -F'\t' 'FNR == NR { if ($1 == "file") keep[$6] = 1; else if ($1 == "shortcut" || $1 == "link") keep[$2] = 1; next }
        $1 == "file" && !($6 in keep) { print $6 }
        ($1 == "shortcut" || $1 == "link") && !($2 in keep) { print $2 }' "$VI_NEWSTATE" "$old" > "$VI_TMP/dropped"
    while IFS= read -r vi_p; do vi_aside "$vi_p"; done < "$VI_TMP/dropped"

    # 7. the install record, then the commit
    vi_record_json "$VI_NEWSTATE" > "$VI_TMP/record.json"
    vi_put "$VI_TMP/record.json" "$dir/install-manifest.json" 644
    vi_put "$VI_TMP/record.json" "$VI_REG/$VI_ID.json" 644
    vi_put "$VI_NEWSTATE" "$VI_REG/$VI_ID.state" 644
    vi_tx_commit

    # 8. after the commit: default handlers, the desktop's caches, and folders an archive left empty
    awk -F'\t' '$1 == "assoc" && $4 == "1" { print $3 "\t" $5 }' "$old" | while IFS="$vi_tab" read -r mime id; do
        grep -qx "$mime$vi_tab$id" "$VI_TMP/defaults" || vi_mimeapps_drop "$mime" "$id"
    done
    vi_refresh_desktop
    while IFS="$vi_tab" read -r mime id; do
        xdg-mime default "$id" "$mime" 2>/dev/null || vi_warn "Could not make $VI_NAME the default for $mime."
    done < "$VI_TMP/defaults"
    awk -F'\t' '$1 == "archive" { print $5 }' "$VI_NEWSTATE" | while IFS= read -r vi_a; do
        [ -d "$vi_a" ] && find "$vi_a" -mindepth 1 -depth -type d -empty -exec rmdir {} \; 2>/dev/null
    done
    # what this install downloaded is in place now
    printf '%s' "$VI_USED" | while IFS= read -r vi_c; do [ -n "$vi_c" ] && rm -f -- "$vi_c"; done

    vi_say ""
    vi_say "$VI_NAME $want installed."
    vi_say "    Location:  $dir"
    vi_say "    Manifest:  $VI_REG/$VI_ID.json"
    vi_say "    Update:    $dir/update.sh"
    vi_say "    Uninstall: $dir/uninstall.sh"
    if grep -q "^link$vi_tab" "$VI_NEWSTATE"; then
        case ":${PATH:-}:" in
            *":$bindir:"*) ;;
            *) vi_say "    $bindir is not on your PATH yet; most distributions add it when you log in again." ;;
        esac
    fi
    return 0
}

vi_main "$@"
